AND t1.mtcd_grp_id IN (
   SELECT 
      t2.mtcd_grp_id
   FROM dtmeta.tb_portal_code t2
   WHERE t2.mtcd = #{mtcd}
)

mapper.insert:
INSERT /* SQL_ID: CodeGroupMapper.insertCodeGroup */
       INTO dtmeta.tb_portal_codegroup
	 ( mtcd_grp_id	
	, mtcd_grp_nm	
	, mtcd_grp_use_yn	
	, mtcd_grp_desc	
	, up_mtcd_grp_id
	, mtcd_grp_sys_usg_yn
	, mtcd_grp_regr_id	
	, mtcd_grp_regr_nm	
	, mtcd_grp_reg_dt	
	, mtcd_grp_amdr_id
	, mtcd_grp_amdr_nm
	, mtcd_grp_amd_dt			 	 
	 ) VALUES 
	 ( #{mtcdGrpId}
	 , #{mtcdGrpNm}
	 , #{mtcdGrpUseYn}
	 , #{mtcdGrpDesc}
	 , #{upMtcdGrpId}
	 , #{mtcdGrpSysUsgYn}
	 , #{mtcdGrpRegrId}
	 , #{mtcdGrpRegrNm}
	 , current_timestamp 
	 , #{mtcdGrpAmdrId}
	 , #{mtcdGrpAmdrNm}
	 , current_timestamp
	 )


SELECT
	'MCG'
	|| LPAD( CAST( CAST( REGEXP_REPLACE( MAX(split_part(mtcd_grp_id, 'MCG', 2)) , '[^0-9]', '', 'g') AS NUMERIC) + 1 AS CHARACTER VARYING)
			, CHAR_LENGTH( REGEXP_REPLACE( MAX(split_part(mtcd_grp_id, 'MCG', 2)) , '[^0-9]', '', 'g'))
			, '0')
FROM dtmeta.tb_portal_codegroup


INSERT /* SQL_ID: CodeGroupMapper.insertCodeGroup */
       INTO dtmeta.tb_portal_codegroup
	 ( mtcd_grp_id	
	, mtcd_grp_nm	
	, mtcd_grp_use_yn	
	, mtcd_grp_desc	
	, up_mtcd_grp_id
	, mtcd_grp_sys_usg_yn	
	, mtcd_grp_regr_id	
	, mtcd_grp_regr_nm	
	, mtcd_grp_reg_dt
	, mtcd_grp_amdr_id
	, mtcd_grp_amdr_nm
	, mtcd_grp_amd_dt			
	 ) VALUES 
	 ( 
	   #{mtcdGrpId}			 			 
	 , #{mtcdGrpNm}
	 , #{mtcdGrpUseYn}
	 , #{mtcdGrpDesc}
	 , #{upMtcdGrpId}
	 , #{mtcdGrpSysUsgYn}
	 , #{mtcdGrpRegrId}
	 , #{mtcdGrpRegrNm}
	 , current_timestamp
	 , #{mtcdGrpAmdrId}
	 , #{mtcdGrpAmdrNm}
	 , current_timestamp
	 )

mapper.update:
		UPDATE /* SQL_ID: CodeGroupMapper.updateCodeGroup */
               dtmeta.tb_portal_codegroup
		   SET mtcd_grp_nm       	= #{mtcdGrpNm}
			 , mtcd_grp_use_yn      = #{mtcdGrpUseYn}
             , mtcd_grp_desc        = #{mtcdGrpDesc}
             , up_mtcd_grp_id       = #{upMtcdGrpId}
             , mtcd_grp_sys_usg_yn  = #{mtcdGrpSysUsgYn}
			 , mtcd_grp_amdr_id     = #{mtcdGrpAmdrId}
			 , mtcd_grp_amdr_nm     = #{mtcdGrpAmdrNm}
			 , mtcd_grp_amd_dt      = current_timestamp			 			 
		 WHERE mtcd_grp_id          = #{mtcdGrpId}

mapper.select:
SELECT EXISTS (
	SELECT 1
	FROM dtmeta.tb_portal_codegroup
	WHERE mtcd_grp_id = #{mtcdGrpId}
)
